// Run on fresh local demo state at desktop and phone widths.
(async()=>{
  const wait=()=>new Promise(r=>setTimeout(r,170));
  const check=(v,m)=>{if(!v)throw Error(m);};
  const state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
  const go=async path=>{location.hash=path;await wait();};
  const click=async(label,scope=document)=>{const button=[...scope.querySelectorAll('button')].find(el=>el.textContent.trim()===label);check(button,`Missing ${label}`);button.click();await wait();};
  const fill=async(label,value)=>{const input=document.querySelector(`[name="${label}"]`);check(input,label);Object.getOwnPropertyDescriptor(input.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(input,value);input.dispatchEvent(new Event('input',{bubbles:true}));await wait();};
  await go('/members');
  check([...document.querySelectorAll('.org-person-row .org-row-tag')].every(el=>el.textContent==='Human'),'Mixed organization roster');
  check(!document.querySelector('.org-tabs').textContent.includes('工作小团队'),'Team under organization');
  await go('/agents');
  check([...document.querySelectorAll('.agent-card h2')].map(el=>el.textContent).join(',')==='Atlas,Muse,Verifier','Human-created roster incorrect');
  const path=location.hash;await click('Agent 创建 · 1');
  check(location.hash===path,'Source filter changed route');
  check(document.querySelectorAll('.agent-card').length===1&&document.querySelector('.agent-card h2').textContent==='Quill','Agent-created roster incorrect');
  check(document.querySelector('.agent-card footer').textContent.includes('Atlas'),'Creator absent');
  await go('/agents/atlas');
  check(document.querySelector('main').textContent.includes('Quill'),'Child lineage not displayed');
  await click('模拟子 Agent 创建提案');
  for(const [label,value] of [['Agent 名称','动态研究员'],['角色','研究'],['职责与边界','核对任务输入'],['System prompt（长期指令）','不编造证据']])await fill(label,value);
  document.querySelector('[aria-label="模型配置引用"]').click();await wait();
  [...document.querySelectorAll('[role=option]')].find(el=>el.textContent.includes('团队文本模型')).click();await wait();
  await click('提交配置提案',document.querySelector('dialog'));
  check(!document.querySelector('dialog'),'Child proposal failed');
  const child=state().agents.find(a=>a.name==='动态研究员');
  check(child?.creatorKind==='Agent'&&child.creatorId==='atlas'&&child.status==='待批准','Creator or approval lost');
  const org=JSON.stringify(state().organization);
  await go('/agents/atlas');await click('退役');
  const dialog=document.querySelector('dialog');check(dialog,'Retirement needs confirmation');
  const confirm=[...dialog.querySelectorAll('button')].find(el=>el.textContent.trim()==='确认继续');check(confirm,'Confirmation absent');confirm.click();await wait();
  check(state().agents.find(a=>a.id==='atlas').status==='退役','Parent not retired');
  check(state().agents.some(a=>a.id===child.id)&&state().agents.some(a=>a.id==='quill'),'Child automatically deleted');
  check(JSON.stringify(state().organization)===org,'Lifecycle changed Human organization');
  await go('/agents');await click('Agent 创建 · 2');
  check(document.querySelectorAll('.agent-card').length===2,'Children disappeared from own roster');
  check(document.documentElement.scrollWidth<=innerWidth+1,'Agent roster overflow');
  return {pass:true,checks:['Human-only organization','separate source lists','in-place filter','creator hierarchy','child proposal awaiting approval','no cascade deletion','identity isolation','responsive width']};
})();
